static int CmpFontUrl(const void* key, const void* elem) {
    return strcmp((const char*)key, ((const SumatraFontUrl*)elem)->name);
}

const char* sumatra_lookup_font_url(const char* name) {
    const SumatraFontUrl* e;
    if (!name) {
        return NULL;
    }
    e = (const SumatraFontUrl*)bsearch(name, kFontUrls, sizeof(kFontUrls) / sizeof(kFontUrls[0]), sizeof(kFontUrls[0]),
                                       CmpFontUrl);
    return e ? e->url : NULL;
}

int sumatra_font_count(void) {
    return (int)(sizeof(kFontUrls) / sizeof(kFontUrls[0]));
}

// i-th font by name; NULL past the end
const char* sumatra_font_at(int i, const char** url, int* size) {
    if (i < 0 || i >= sumatra_font_count()) {
        return NULL;
    }
    *url = kFontUrls[i].url;
    *size = kFontUrls[i].size;
    return kFontUrls[i].name;
}
